def _classify_kind(term, part_of_speech):
    term = term.strip()
    if term.endswith((".", "!", "?", "。", "！", "？")):
        return "sentence"
    if any(character.isspace() for character in term) or part_of_speech.strip().casefold() in {
        "redewendung", "wortverbindung"
    }:
        return "expression"
    return "word"


def _default_note(kind, translation_zh):
    translation = translation_zh.strip()
    if kind == "expression":
        return f"表示“{translation}”的常用表达。" if translation else "C1 Hochschule 常用表达。"
    if kind == "sentence":
        return f"用于表达“{translation}”的完整句型。" if translation else "C1 Hochschule 常用句型。"
    return ""


def backfill_vocabulary_kind_and_note(apps, schema_editor):
    Card = apps.get_model("exam_preparation", "ExamVocabularyCard")
    for card in Card.objects.all().iterator():
        kind = _classify_kind(card.term, card.part_of_speech)
        updates = {"kind": kind}
        if kind in {"expression", "sentence"} and not card.note.strip():
            updates["note"] = _default_note(kind, card.translation_zh)
        Card.objects.filter(pk=card.pk).update(**updates)


